DAYS = ['الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت', 'الأحد']
MONTHS = {11: 'نوفمبر', 12: 'ديسمبر', 1: 'يناير'}
def series(date, slot):
    wd = dt.date.fromisoformat(date).weekday()
    if slot == 'am': return 'آية الصباح'
    return {4: 'جمعة مباركة', 3: 'من أذكار المساء', 6: 'دعاء من القرآن', 0: 'قارئ الأسبوع'}.get(wd, 'آية وتدبّر')
def item(n, date, slot, rec, vs, quote, note, bg, bgn):
    ch, rng = vs.split(':'); ch = int(ch)
    a, b = (rng.split('-') + [rng])[:2]
    verses = [f'{ch}:{v}' for v in range(int(a), int(b) + 1)]
    name, label, expect, photo, tag = R[rec]
    hour, ampm = (7, 'صباحًا') if slot == 'am' else (21, 'مساءً')
    d = dt.date.fromisoformat(date)
    ser = series(date, slot)
    surah = 'سورة ' + SURAH[ch]
    first = verses[0].split(':')[1]
    return {
      'id': f"{n}-{slot}-{tag.split('_')[0] if tag != 'عبد_الباسط_عبد_الصمد' else 'abdulbasit'}-{ch}-{first}".replace('الحصري', 'husary').replace('المنشاوي', 'minshawi').replace('العفاسي', 'alafasy'),
      'at': f'{date}T{hour:02d}:00:00+03:00',
      'when': f'{DAYS[d.weekday()]} {d.day} {MONTHS[d.month]} · {hour if hour <= 12 else hour - 12}:00 {ampm}',
      'type': 'reel', 'platforms': ['facebook', 'instagram', 'youtube'],
      'style': 'place', 'background': 'commons:' + bg, 'background_n': bgn, 'series': ser,
      'reciter': name, 'label': label, 'recitation': rec, 'expect': expect, 'verses': verses, 'surah': surah, 'photo': photo,
      'title': f'﴿{quote}﴾ | {ser} | Cairo Quran',
      'caption': f"{{{{verse}}}}\n\n{{{{ref}}}}\nبصوت الشيخ {name}\n\n{note}\n\n#{ser.replace(' ', '_')} #{surah.replace(' ', '_')} #{tag} #قرآن_كريم #CairoQuran",
    }
def week_of(date):
    d = dt.date.fromisoformat(date)
    if d < dt.date(2026, 12, 2): return '2026-11-18'
    start = dt.date(2026, 12, 2)
    return (start + dt.timedelta(days=7 * ((d - start).days // 7))).isoformat()
weeks, used = {}, {}
for slot, rows, pool in (('am', AM, AM_BG), ('pm', PM, PM_BG)):
    for i, (date, rec, vs, quote, note) in enumerate(rows):
        bg = pool[i % len(pool)]; bgn = used.get(bg, 0); used[bg] = bgn + 1
        weeks.setdefault(week_of(date), []).append((date, slot, rec, vs, quote, note, bg, bgn))
for w, rows in sorted(weeks.items()):
    rows.sort(key=lambda r: (r[0], r[1] == 'pm'))
    items = [item(n + 1, *r) for n, r in enumerate(rows)]
    os.makedirs(os.path.join(OUT, w), exist_ok=True)
    with open(os.path.join(OUT, w, 'reels.json'), 'w', encoding='utf-8') as f: json.dump(items, f, ensure_ascii=False, indent=2); f.write('\n')
    print(w, len(items), items[0]['at'], '->', items[-1]['at'])
